function binarySearch(arr, target) {
  let lo = 0;
  let hi = arr.length - 1;
  while (lo < hi) {            // BUG A
    const mid = lo + Math.floor((hi - lo) / 2);
    if (arr[mid] === target) {
      return mid;
    } else if (arr[mid] < target) {
      lo = mid;               // BUG B
    } else {
      hi = mid - 1;
    }
  }
  return -1;
}

const a = [1, 3, 5, 7, 9, 11, 13];
console.log(
  binarySearch(a, 7),   // 3
  binarySearch(a, 1),   // 0
  binarySearch(a, 13),  // 6
  binarySearch(a, 6),   // -1
  binarySearch([42], 42) // 0
);

