function lowerBound(arr, target) {
  let lo = 0;
  let hi = arr.length; // note: hi is exclusive here
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (arr[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid;            // do not stop on equality — shrink toward the left
    }
  }
  return lo;
}

const a = [1, 1, 2, 2, 2, 5, 8, 8];
console.log(
  lowerBound(a, 2),  // 2  (first 2 is at index 2)
  lowerBound(a, 1),  // 0  (first 1 is at index 0)
  lowerBound(a, 8)   // 6  (first 8 is at index 6)
);

