function search(arr, t) {
  let lo = 0, hi = arr.length - 2;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] === t) return mid;
    if (arr[mid] < t) lo = mid + 1; else hi = mid - 1;
  }
  return -1;
}

